input.command:
$text = Get-Content -Raw -Encoding UTF8 "F:\obsidian_notes\knowledge\TOEFL\学术讨论\AI伦理问题.md"
# Extract original 10 sentences and the 10 quoted sentences in 逐句纠错
$origBlock = [regex]::Match($text, '(?s)# 我的答案\s*\r?\n\r?\n(.*?)\r?\n\r?\n# 评审意见').Groups[1].Value -split '\r?\n'
$origSents = @(); foreach ($line in $origBlock) { if ($line.Trim() -ne '') { $origSents += [regex]::Matches($line, '[A-Za-z].*?[.!?](?:\s|$)') | ForEach-Object { $_.Value.Trim() } } }
"== Original 10 sentences (count: $($origSents.Count)) =="
$i = 1; foreach ($s in $origSents) { "$i. $s"; $i++ }
# Compare with each quoted sentence in review sections
$quoted = [regex]::Matches($text, '(?m)^> (I totally concur|Although the wide-use|For example, AI helps|Besides, especially|As the AI paiting|The related laws|As for Andrew|Firstly, AI|In addition, the cost|In conclusion, I think).*$')
"== Quoted sentences in 逐句纠错 (count: $($quoted.Count)) =="
$i = 1; foreach ($q in $quoted) { "$i. $($q.Groups[0].Value)"; $i++ }
